// Machine Program service worker: offline use and updates. The build (tools/pwa.mjs) writes BUILD on the first line:
// { version, files: [[path, sha256 base64], ...], cdn: { three, fonts } }.
// - install: this version's files (the page, the engine, the data, the exercises, the icons, the manifest) go into
//   mp-app-<version>, each checked against the build's SHA-256, so a cache never mixes two versions (a file an older
//   version holds with the same content is copied over instead of downloaded again); three.js and the Google Fonts CSS
//   go into mp-cdn if they are not there yet (best effort)
// - fetch: the app's files from this version's cache; three.js and Google Fonts cache first from mp-cdn, kept there on
//   first use (the page also hands over what it loaded before this worker was in charge); opening the app gets the
//   cached page
// - updates: a new version installs in the background and waits; the next time the app is opened (or reloaded while no
//   other window of it is open) it takes over at once; activating deletes the older versions' caches
// - the end of a rest: the page posts { type: 'rest', at } (at 0: none) when a rest starts, is skipped, undone or restored, and
//   when the app goes out of sight; the worker holds the time in event.waitUntil (Chromium keeps a worker alive for an event up
//   to 5 min, and a rest is shorter) and then shows "Rest over" only if no window of the app is in sight (in sight, the page
//   beeps and buzzes itself); a tap on it brings the app back. { type: 'rest', test: true } always shows (the menu's test).
'use strict';
const APP = 'mp-app-' + BUILD.version, CDN = 'mp-cdn';
const CDN_HOSTS = ['cdn.jsdelivr.net', 'fonts.googleapis.com', 'fonts.gstatic.com'];
const SCOPE = self.registration.scope, SCOPE_PATH = new URL(SCOPE).pathname, INDEX = new URL('index.html', SCOPE).href;
const THREE = new URL(BUILD.cdn.three).href, FONTS = new URL(BUILD.cdn.fonts).href;
const SUM = 'x-mp-sha256'; // a cached file's hash, compared by the next version's install
const TYPES = { html: 'text/html; charset=utf-8', js: 'text/javascript; charset=utf-8', json: 'application/json', png: 'image/png', webp: 'image/webp', webmanifest: 'application/manifest+json' };
// the page a launch gets while a waiting new version takes over (it asks for the app again at once; the empty icon
// keeps the browser from asking the site's root for a favicon.ico)
const SWITCH = '<!doctype html><meta charset="utf-8"><meta name="color-scheme" content="dark"><meta http-equiv="refresh" content="0">'
  + '<link rel="icon" href="data:,"><title>Machine Program</title><style>html{background:#0a0e11}</style>';

const isCdn = (u) => u.protocol === 'https:' && CDN_HOSTS.includes(u.hostname);
const b64 = (buf) => { const a = new Uint8Array(buf); let s = ''; for (let i = 0; i < a.length; i += 0x8000) s += String.fromCharCode.apply(null, a.subarray(i, i + 0x8000)); return btoa(s); };
const sha = async (buf) => b64(await crypto.subtle.digest('SHA-256', buf));

async function precache() {
  const cache = await caches.open(APP);
  const older = (await caches.keys()).filter((k) => k.startsWith('mp-app-') && k !== APP);
  await Promise.all(BUILD.files.map(async ([path, sum]) => {
    const url = new URL(path, SCOPE).href;
    const have = await cache.match(url);
    if (have && have.headers.get(SUM) === sum) return; // (an install of this version tried before)
    for (const k of older) {
      const r = await (await caches.open(k)).match(url);
      if (r && r.headers.get(SUM) === sum) { await cache.put(url, r); return; }
    }
    const res = await fetch(url, { cache: 'no-cache' });
    if (!res.ok) throw new Error('precache ' + path + ': HTTP ' + res.status);
    const buf = await res.arrayBuffer();
    if ((await sha(buf)) !== sum) throw new Error('precache ' + path + ': not the file of this version');
    const type = res.headers.get('content-type') || TYPES[path.split('.').pop()] || 'application/octet-stream';
    await cache.put(url, new Response(buf, { status: 200, statusText: 'OK', headers: { 'Content-Type': type, [SUM]: sum } }));
  }));
}

// three.js and the fonts CSS (their urls are part of the build) into the CDN cache, unless they are there
async function warmCdn() {
  const cache = await caches.open(CDN);
  await Promise.all([THREE, FONTS].map((u) => keepOne(cache, u)));
}
async function keepOne(cache, u) {
  try {
    if (await cache.match(u, { ignoreVary: true })) return;
    const r = await fetch(u, { mode: 'cors', credentials: 'omit' });
    if (r.ok) await cache.put(u, r);
  } catch (_) { /* kept on first use instead */ }
}
// what a page loaded from the CDNs itself (before this worker was in charge of it)
async function keepCdn(urls) {
  const cache = await caches.open(CDN);
  for (const u of urls.slice(0, 64)) {
    let url; try { url = new URL(u); } catch (_) { continue; }
    if (isCdn(url)) await keepOne(cache, url.href);
  }
}
// keep three.js, the fonts CSS and the font files it names; drop what older versions used (only once the CSS is there)
async function pruneCdn() {
  const cache = await caches.open(CDN);
  const css = await cache.match(FONTS, { ignoreVary: true });
  if (!css) return;
  const keep = new Set([THREE, FONTS]);
  for (const m of (await css.text()).matchAll(/url\((['"]?)(https:\/\/fonts\.gstatic\.com\/[^'")\s]+)\1\)/g)) keep.add(new URL(m[2]).href);
  for (const req of await cache.keys()) if (!keep.has(req.url)) await cache.delete(req);
}

self.addEventListener('install', (event) => { event.waitUntil(Promise.all([precache(), warmCdn()])); });

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('mp-app-') && k !== APP) await caches.delete(k);
    try { await pruneCdn(); } catch (_) { /* the next version tidies up */ }
    await self.clients.claim();
  })());
});

// the one rest the worker waits for (and the menu's test, in a slot of its own): a newer message replaces it (and lets the old
// wait end at once)
const alarms = { rest: { timer: 0, done: null }, test: { timer: 0, done: null } };
function restDisarm(a) { if (a.timer) clearTimeout(a.timer); a.timer = 0; if (a.done) a.done(); a.done = null; }
function restArm(event, d) {
  const a = alarms[d.test ? 'test' : 'rest'];
  restDisarm(a);
  const at = +d.at || 0, wait = at - Date.now();
  if (!(at > 0) || wait > 270000) return; // (none, or longer than one event may last: the page's own timer is all there is)
  event.waitUntil(new Promise((resolve) => {
    a.done = resolve;
    a.timer = setTimeout(async () => {
      a.timer = 0; a.done = null;
      try {
        const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
        if (d.test || !wins.some((w) => w.visibilityState === 'visible')) {
          await self.registration.showNotification(String(d.title || 'Rest over').slice(0, 80), {
            body: String(d.body || '').slice(0, 160), tag: 'rest', renotify: true, vibrate: [200, 100, 200], timestamp: at,
            icon: new URL('icons/icon-192.png', SCOPE).href, data: { url: SCOPE },
          });
        }
      } catch (_) { /* no permission, or nothing to show it on */ }
      resolve();
    }, Math.max(0, wait));
  }));
}

self.addEventListener('message', (event) => {
  const d = event.data;
  if (!d || typeof d !== 'object') return;
  // from the version before this one, when the app is opened again: take over now
  if (d.type === 'skip-waiting') self.skipWaiting();
  else if (d.type === 'keep' && Array.isArray(d.urls)) event.waitUntil(keepCdn(d.urls));
  else if (d.type === 'rest') restArm(event, d);
});

// a tap on the notification: the app's window, or the app opened
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const w of wins) if (w.url.startsWith(SCOPE) && 'focus' in w) return w.focus();
    if (self.clients.openWindow) return self.clients.openWindow((event.notification.data && event.notification.data.url) || SCOPE);
    return null;
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (req.mode === 'navigate') { if (url.href.startsWith(SCOPE)) event.respondWith(openPage(req, url)); return; }
  if (url.origin === self.location.origin) { if (url.href.startsWith(SCOPE)) event.respondWith(appFile(req)); return; }
  if (isCdn(url)) event.respondWith(cdnFile(event, req));
});

async function openPage(req, url) {
  // a new version is waiting and this is the only window of the app (it is being opened or reloaded): switch now
  const reg = self.registration;
  if (reg.waiting && (await self.clients.matchAll({ type: 'window' })).length < 2) {
    reg.waiting.postMessage({ type: 'skip-waiting' });
    return new Response(SWITCH, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', Refresh: '0' } });
  }
  const rel = url.pathname.slice(SCOPE_PATH.length);
  if (rel === '' || rel === 'index.html') return (await caches.match(INDEX, { cacheName: APP })) || fetch(req);
  // any other address in the app's folder: the network; offline, the app itself
  try { return await fetch(req); } catch (_) { return Response.redirect(SCOPE, 302); }
}

async function appFile(req) {
  return (await caches.match(req, { cacheName: APP })) || fetch(req);
}

async function cdnFile(event, req) {
  const cache = await caches.open(CDN);
  const hit = await cache.match(req, { ignoreVary: true });
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) event.waitUntil(cache.put(req, res.clone()).catch(() => {}));
  return res;
}
